@override Widget build(BuildContext context){final money=NumberFormat.currency(locale:'id_ID',symbol:'Rp ',decimalDigits:0);return RefreshIndicator(onRefresh:_refresh,child:FutureBuilder<List<CreditBalance>>(future:_future,builder:(context,snapshot){final all=snapshot.data??const <CreditBalance>[];final now=DateTime.now(),today=DateTime(now.year,now.month,now.day);final filtered=all.where((c){final q=_query.toLowerCase(),match=q.isEmpty||c.transactionNo.toLowerCase().contains(q);if(_filter=='overdue')return match&&c.dueDate!=null&&c.dueDate!.isBefore(today);if(_filter=='due')return match&&c.dueDate!=null&&!c.dueDate!.isBefore(today)&&c.dueDate!.isBefore(now.add(const Duration(days:7)));return match;}).toList();final total=all.fold<double>(0,(x,e)=>x+e.balance),overdue=all.where((e)=>e.dueDate!=null&&e.dueDate!.isBefore(today)).fold<double>(0,(x,e)=>x+e.balance);return ListView(padding:const EdgeInsets.fromLTRB(16,12,16,28),children:[const IrkopSectionHeader(eyebrow:'Piutang pelanggan',title:'Kasbon',subtitle:'Pantau tagihan, jatuh tempo dan pembayaran kasbon.',icon:Icons.credit_score_outlined,action:'Data aktual'),const SizedBox(height:14),Row(children:[Expanded(child:_Summary(icon:Icons.account_balance_wallet_outlined,label:'Piutang Aktif',value:money.format(total))),const SizedBox(width:10),Expanded(child:_Summary(icon:Icons.warning_amber_outlined,label:'Terlambat',value:money.format(overdue)))]),const SizedBox(height:16),TextField(onChanged:(v)=>setState(()=>_query=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari nomor kasbon')),const SizedBox(height:10),SegmentedButton<String>(segments:const [ButtonSegment(value:'active',label:Text('Aktif')),ButtonSegment(value:'due',label:Text('7 Hari')),ButtonSegment(value:'overdue',label:Text('Terlambat'))],selected:{_filter},onSelectionChanged:(v)=>setState(()=>_filter=v.first)),const SizedBox(height:14),if(snapshot.connectionState!=ConnectionState.done)const LinearProgressIndicator(),if(snaps