Future<void> _detail(CreditBalance c)async{final m=NumberFormat.currency(locale:'id_ID',symbol:'Rp ',decimalDigits:0);await showModalBottomSheet<void>(context:context,builder:(x)=>SafeArea(child:Padding(padding:const EdgeInsets.all(20),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Detail Kasbon',style:Theme.of(x).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:12),_row('Nomor',c.transactionNo),_row('Total',m.format(c.total)),_row('Terbayar',m.format(c.paid)),_row('Sisa',m.format(c.balance)),if(c.dueDate!=null)_row('Jatuh tempo',DateFormat('dd MMMM yyyy','id_ID').format(c.dueDate!)),const SizedBox(height:14),SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:(){Navigator.pop(x);_pay(c);},icon:const Icon(Icons.payments_outlined),label:const Text('Bayar Kasbon')))]))));}
